// Helper function to build a min-heap from an array.
void _buildMinHeap(List<int> heap) {
  for (int i = heap.length ~/ 2 - 1; i >= 0; i--) {
    _minHeapify(heap, i);
  }
}

// Helper function to insert a value into a min-heap.
void _insertIntoMinHeap(int value, List<int> heap) {
  heap.add(value);
  int index = heap.length - 1;
  while (index > 0 && heap[index] < heap[(index - 1) ~/ 2]) {
    final parentIndex = (index - 1) ~/ 2;
    heap.swap(parentIndex, index);
    index = parentIndex;
  }
}

// Helper function to remove the minimum value from a min-heap.
int _removeFromMinHeap(List<int> heap) {
  final minVal = heap.first;
  final lastElement = heap.removeLast();
  if (!heap.isEmpty) {
    heap.insertFirst(lastElement);
    _minHeapify(heap, 0);
  }
  return minVal;
}

// Helper function to maintain the min-heap property at a given node.
void _minHeapify(List<int> heap, int idx) {
  final leftChild = 2 * idx + 1;
  final rightChild = 2 * idx + 2;
  int smallest = idx;

  if (leftChild < heap.length && heap[leftChild] < heap[smallest]) {
    smallest = leftChild;
  }
  if (rightChild < heap.length && heap[rightChild] < heap[smallest]) {
    smallest = rightChild;
  }

  if (smallest != idx) {
    heap.swap(idx, smallest);
    _minHeapify(heap, smallest);
  }
}

