int _countUpperCase(String str) => str.toUpperCase() == str ? str.length : 0;

bool _isCaseAlternating(String str) {
  bool prevUpper = false;
  for (var c in str.codeUnits) {
    var isCurrentUpper = (c >= 'A'.codeUnitAt(0) && c <= 'Z'.codeUnitAt(0));
    if ((prevUpper && isCurrentUpper) || (!prevUpper && !isCurrentUpper)) {
      return false; // Not alternating
    }
    prevUpper = isCurrentUpper;
  }
  return true; // Alternates upper/lowercase or all same case
}

