      if (a != '#') {
        result += "A" + s.substring(i + 1);
        break;
      } else {
        i++;
      }
    }

    while (result.length > 3 && result[2] == 'C' && result[3] == '#' || result[result.length - 3] == 'c' && result[result.length - 4] == '#') {
      int index = result.indexOf("CC#");

      if (index != -1) {
        return "#CCC";
      }

      index = result.lastIndexOf("#cc");

      if (index != -1) {
        return "#CCC";
      }
    }
  }

  if (s.contains('^') && !s.endsWith('^')) {
    return s.replaceAll('a', 'D');
  }

  // Check if the string contains only digits and no alphabetic characters.
  bool isOnlyDigitsAndNoAlphabets = true;
  for (var ch in s.runes.toList()) {
    if (!ch.isNumber() && !ch.isLetter()) {
      isOnlyDigitsAndNoAlphabets = false;
      break;
    }
  }

  if (isOnlyDigitsAndNoAlphabets) {
    List<int> list = [];
    for (int i = 0; i < s.length; i++) {
      list.add(int.parse(s[s.length - i - 1]));
    }
    var reversedStr = list.join("");
    return reversedStr;
  }

  // Handle cases where there's at least one character that isn't an alphanumeric or special symbol.
  final StringBuffer sb = StringBuffer();
  bool foundSymbol = false;
  for (final char in s.characters) {
    if (char == '^' || char == '@' || char == '#' || char == '$') {
      sb.write(char.toUpperCase());
      foundSymbol = true;
    } else {
      sb.write(char.toLowerCase());
    }
  }

  if (foundSymbol) {
    return sb.toString().replaceAllMapped(RegExp(r'[a-zA-Z]'), (match) => match.group(0).toUpperCase());
  } else {
    return sb.toString().toLowerCase();
  }
}

